<?php get_header(); if ( staffswap_builder_location( 'single' ) ) { get_footer(); return; } while ( have_posts() ) : the_post(); ?>
<article class="single-article"><p class="eyebrow"><?php echo esc_html( get_the_date() ); ?></p><h1><?php the_title(); ?></h1><div class="single-article__body"><?php the_content(); ?></div><div class="single-article__share"><span class="muted"><?php echo esc_html__( 'Share:', 'staffswap' ); ?></span><a href="<?php echo esc_url( 'https://wa.me/?text=' . rawurlencode( get_the_title() . ' ' . get_permalink() ) ); ?>" target="_blank" rel="noopener">WhatsApp</a><a href="<?php echo esc_url( 'https://www.facebook.com/sharer/sharer.php?u=' . rawurlencode( get_permalink() ) ); ?>" target="_blank" rel="noopener">Facebook</a><a href="<?php echo esc_url( 'https://twitter.com/intent/tweet?url=' . rawurlencode( get_permalink() ) . '&text=' . rawurlencode( get_the_title() ) ); ?>" target="_blank" rel="noopener">X</a><a href="<?php echo esc_url( 'mailto:?subject=' . rawurlencode( get_the_title() ) . '&body=' . rawurlencode( get_permalink() ) ); ?>">Email</a></div><?php
	$staffswap_related = new WP_Query( array( 'post_type' => 'post', 'post_status' => 'publish', 'post__not_in' => array( get_the_ID() ), 'posts_per_page' => 3, 'category__in' => wp_get_post_categories( get_the_ID() ) ) );
	if ( $staffswap_related->have_posts() ) : ?><section style="margin-top:32px"><div class="page-heading"><div><p class="eyebrow"><?php echo esc_html__( 'KEEP READING', 'staffswap' ); ?></p><h2><?php echo esc_html__( 'Related articles', 'staffswap' ); ?></h2></div></div><div class="article-grid"><?php while ( $staffswap_related->have_posts() ) : $staffswap_related->the_post(); ?><article class="article-card"><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 18 ) ); ?></p></article><?php endwhile; wp_reset_postdata(); ?></div></section><?php endif;
?><p style="margin-top:24px"><a class="button button--outline" href="<?php echo esc_url( home_url( '/blog/' ) ); ?>">&larr; <?php echo esc_html__( 'Back to Blog', 'staffswap' ); ?></a></p></article>
<?php if ( comments_open() || get_comments_number() ) : comments_template(); endif; ?>
<?php endwhile; get_footer(); ?>
